struct ra_tag { int _dummy; };              /* empty tag types, by convention */
struct fwd_tag { int _dummy; };
static long dist_ra(const int *a, const int *b);
static long dist_fwd(const int *a, const int *b);

/* the TYPE of the tag selects the function; nothing is read at run time */
#define dist(tag, a, b) _Generic((tag),  \
    struct ra_tag: dist_ra, struct fwd_tag: dist_fwd)((a), (b))
